input.content:
:root {
  --bg: #f5f6f8; --card: #ffffff; --ink: #1f2430; --muted: #6b7280;
  --line: #e5e7eb; --accent: #2f6feb; --accent-soft: #eaf1fe;
}
* { box-sizing: border-box; }
body {
  margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg); color: var(--ink);
}
header { background: var(--card); border-bottom: 1px solid var(--line); padding: 18px 24px; }
header h1 { margin: 0; font-size: 20px; }
header p { margin: 4px 0 0; color: var(--muted); font-size: 13px; }
.variant-tag { display:inline-block; margin-top:8px; font-size:12px; font-weight:600;
  color: var(--accent); background: var(--accent-soft); padding: 3px 10px; border-radius: 999px; }
.wrap { max-width: 720px; margin: 0 auto; padding: 24px; }

.card { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 18px; }
.card .title { font-size: 16px; font-weight: 600; margin: 0 0 4px; }
.card .site { color: var(--accent); font-size: 12px; margin: 0 0 8px; }
.card .desc { color: var(--muted); font-size: 13px; margin: 0 0 14px; line-height: 1.45; }

.field-label { font-size: 12px; font-weight: 600; color: var(--muted); margin: 14px 0 6px; text-transform: uppercase; letter-spacing: .03em; }

.chips { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.chip { background: var(--accent-soft); color: var(--accent); font-size: 13px;
  padding: 4px 10px; border-radius: 999px; display: inline-flex; align-items: center; gap: 6px; }
.chip button { border: none; background: none; color: var(--accent); cursor: pointer; font-size: 14px; line-height: 1; padding: 0; }

input[type=text], textarea {
  width: 100%; padding: 9px 11px; border: 1px solid var(--line); border-radius: 8px;
  font-size: 14px; font-family: inherit;
}
textarea { min-height: 70px; resize: vertical; }
.taginput { border: 1px solid var(--line); border-radius: 8px; padding: 6px 8px; display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.taginput input { border: none; padding: 4px; flex: 1; min-width: 120px; outline: none; }

.suggests { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.suggests .sug { border: 1px dashed var(--line); background: #fff; color: var(--muted);
  font-size: 12px; padding: 3px 10px; border-radius: 999px; cursor: pointer; }
.suggests .sug:hover { border-color: var(--accent); color: var(--accent); }

.saved-note { color: var(--muted); font-size: 13px; margin-top: 6px; white-space: pre-wrap; }
.hint { color: var(--muted); font-size: 12px; margin-top: 16px; }

