:root {
  --bg: #f5f6f8; --card: #ffffff; --ink: #1f2430; --muted: #6b7280;
  --line: #e5e7eb; --accent: #2f6feb; --accent-soft: #eaf1fe;
  --read: #0a7c47; --read-soft: #e6f6ee; --toread: #b4690e; --toread-soft: #fdf1e1;
}
* { box-sizing: border-box; }
body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: var(--bg); color: var(--ink); }
header { background: var(--card); border-bottom: 1px solid var(--line); padding: 18px 24px; }
header h1 { margin: 0; font-size: 20px; }
header p { margin: 4px 0 0; color: var(--muted); font-size: 13px; }
.variant-tag { display:inline-block; margin-top:8px; font-size:12px; font-weight:600; color: var(--accent); background: var(--accent-soft); padding: 3px 10px; border-radius: 999px; }
.wrap { max-width: 780px; margin: 0 auto; padding: 24px; }

.searchbar { position: relative; margin-bottom: 14px; }
.searchbar input { width: 100%; padding: 11px 14px 11px 38px; border: 1px solid var(--line); border-radius: 10px; font-size: 15px; background: var(--card); }
.searchbar::before { content: "🔍"; position: absolute; left: 12px; top: 10px; font-size: 15px; opacity: .6; }

.browse-label { font-size: 12px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: .03em; margin: 0 0 8px; }
.tagfilters { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.tagfilter { border: 1px solid var(--line); background: var(--card); color: var(--muted); font-size: 13px; padding: 5px 12px; border-radius: 999px; cursor: pointer; }
.tagfilter.active { background: var(--accent); border-color: var(--accent); color: #fff; }

.tabs { display: flex; gap: 6px; margin-bottom: 16px; border-bottom: 1px solid var(--line); }
.tab { padding: 9px 16px; font-size: 14px; font-weight: 600; color: var(--muted); cursor: pointer; border-bottom: 2px solid transparent; margin-bottom: -1px; }
.tab.active { color: var(--accent); border-bottom-color: var(--accent); }

.section-title { font-size: 15px; font-weight: 700; margin: 22px 0 12px; display: flex; align-items: center; gap: 8px; }
.section-title .n { color: var(--muted); font-weight: 500; font-size: 13px; }

.card { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 16px; margin-bottom: 12px; }
.card .top { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; }
.card .title { font-size: 16px; font-weight: 600; margin: 0 0 4px; }
.card .title a { color: var(--ink); text-decoration: none; }
.card .site { color: var(--accent); font-size: 12px; margin: 0 0 8px; }
.card .desc { color: var(--muted); font-size: 13px; margin: 0 0 10px; line-height: 1.45; }
.card .chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.card .chip { background: var(--accent-soft); color: var(--accent); font-size: 12px; padding: 3px 10px; border-radius: 999px; cursor: pointer; }
.card .note { color: #8a5a00; background: #fff8e6; border-radius: 8px; padding: 8px 10px; font-size: 13px; margin: 0 0 8px; }
.card .meta { color: var(--muted); font-size: 12px; }
mark { background: #fff2a8; padding: 0 1px; border-radius: 2px; }

.status-pill { font-size: 12px; font-weight: 600; padding: 3px 10px; border-radius: 999px; white-space: nowrap; }
.status-pill.toread { color: var(--toread); background: var(--toread-soft); }
.status-pill.finished { color: var(--read); background: var(--read-soft); }
.status-toggle { margin-top: 10px; border: 1px solid var(--line); background: #fff; color: var(--ink); font-size: 13px; padding: 6px 12px; border-radius: 8px; cursor: pointer; }
.status-toggle:hover { border-color: var(--accent); color: var(--accent); }

.empty { text-align: center; color: var(--muted); padding: 30px 20px; border: 1px dashed var(--line); border-radius: 12px; background: var(--card); }

