  --note-ink: #8a5a00; --note-bg: #fff8e6;
}
* { box-sizing: border-box; }
body {
  margin: 0; background: var(--bg); color: var(--ink);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.app-header { background: var(--card); border-bottom: 1px solid var(--line); }
.app-header__inner { max-width: 780px; margin: 0 auto; padding: 18px 24px; }
.app-header h1 { margin: 0; font-size: 20px; }
.app-header p { margin: 4px 0 0; color: var(--muted); font-size: 13px; }
.wrap { max-width: 780px; margin: 0 auto; padding: 24px; }

.btn {
  border: 1px solid var(--line); background: #fff; color: var(--ink);
  font-size: 13px; padding: 7px 13px; border-radius: 8px; cursor: pointer;
}
.btn:hover { border-color: var(--accent); color: var(--accent); }
.btn--primary { background: var(--accent); color: #fff; border-color: var(--accent); font-weight: 600; padding: 11px 18px; font-size: 14px; }
.btn--primary:hover { color: #fff; opacity: .95; }
.btn--primary:disabled { opacity: .5; cursor: default; }
.btn--danger { color: var(--danger); border-color: var(--danger-line); }
.btn--danger:hover { background: var(--danger-soft); border-color: var(--danger); color: var(--danger); }
.btn--danger-solid { background: var(--danger); color: #fff; border-color: var(--danger); }
.btn--danger-solid:hover { color: #fff; opacity: .95; }

.saver { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 18px; margin-bottom: 18px; }
.saver label { display: block; font-size: 13px; font-weight: 600; margin-bottom: 8px; }
.saver__row { display: flex; gap: 10px; }
.saver__row input { flex: 1; padding: 11px 12px; border: 1px solid var(--line); border-radius: 8px; font-size: 14px; }
.saver__row input.bad { border-color: var(--danger); background: var(--danger-soft); }
.saver__fetching { font-size: 13px; color: var(--muted); margin-top: 10px; }
.msg { font-size: 13px; margin-top: 10px; }
.msg--err { color: var(--danger); }
.msg--info { color: var(--accent); }

.searchbar { position: relative; margin-bottom: 14px; }
.searchbar input { width: 100%; padding: 12px 14px 12px 40px; border: 1px solid var(--line); border-radius: 10px; font-size: 15px; background: var(--card); }
.searchbar::before { content: "🔍"; position: absolute; left: 13px; top: 11px; font-size: 15px; opacity: .6; }

.tag-browse { margin-bottom: 14px; }
.tag-browse__label { display: block; font-size: 12px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: .03em; margin-bottom: 8px; }
.tag-filters { display: flex; flex-wrap: wrap; gap: 8px; }
.tag-filter { border: 1px solid var(--line); background: var(--card); color: var(--muted); font-size: 13px; padding: 5px 12px; border-radius: 999px; cursor: pointer; }
.tag-filter.active { background: var(--accent); border-color: var(--accent); color: #fff; }

.tabs { display: flex; gap: 6px; margin-bottom: 16px; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.tab { padding: 9px 15px; font-size: 14px; font-weight: 600; color: var(--muted); cursor: pointer; border-bottom: 2px solid transparent; margin-bottom: -1px; background: none; border-top: none; border-left: none; border-right: none; }
.tab.active { color: var(--accent); border-bottom-color: var(--accent); }
.tab--archived { margin-left: auto; }

.card { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 16px; margin-bottom: 12px; }
.card.archived { opacity: .85; background: #fbfbfc; border-style: dashed; }
.card.flash { box-shadow: 0 0 0 2px var(--accent); }
.card__top { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; }
.card .title { font-size: 16px; font-weight: 600; margin: 0 0 4px; overflow-wrap: anywhere; }
.card .title a { color: var(--ink); text-decoration: none; }
.card .title a:hover { text-decoration: underline; }
.card .site { color: var(--accent); font-size: 12px; margin: 0 0 8px; overflow-wrap: anywhere; }
.card .desc { color: var(--muted); font-size: 13px; margin: 0 0 10px; line-height: 1.45; overflow-wrap: anywhere; }
.card .chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.card .chip { background: var(--accent-soft); color: var(--accent); font-size: 12px; padding: 3px 10px; border-radius: 999px; cursor: pointer; border: none; }
.card .note { color: var(--note-ink); background: var(--note-bg); border-radius: 8px; padding: 8px 10px; font-size: 13px; margin: 0 0 8px; overflow-wrap: anywhere; white-space: pre-wrap; }
.card .flag { color: var(--danger); background: var(--danger-soft); border-radius: 8px; padding: 6px 10px; font-size: 12px; display: block; margin-bottom: 8px; }
.card .meta { color: var(--muted); font-size: 12px; margin: 0 0 4px; }
.card__actions { display: flex; gap: 8px; margin-top: 10px; flex-wrap: wrap; }

.status-pill { font-size: 12px; font-weight: 600; padding: 3px 10px; border-radius: 999px; white-space: nowrap; }
.status-pill--toread { color: var(--toread); background: var(--toread-soft); }
.status-pill--finished { color: var(--read); background: var(--read-soft); }

mark { background: #fff2a8; padding: 0 1px; border-radius: 2px; }

.empty { text-align: center; color: var(--muted); padding: 44px 20px; border: 1px dashed var(--line); border-radius: 12px; background: var(--card); }
.empty .big { font-size: 30px; margin-bottom: 8px; }
.empty .t { font-weight: 600; color: var(--ink); margin-bottom: 6px; }
.empty .btn { margin-top: 12px; }

.archive-banner { background: #f0f1f4; border: 1px solid var(--line); color: var(--muted); font-size: 13px; padding: 10px 12px; border-radius: 10px; margin-bottom: 12px; }

/* Inline edit form */
.edit label { display: block; font-size: 12px; font-weight: 600; color: var(--muted); margin: 10px 0 4px; text-transform: uppercase; letter-spacing: .03em; }
.edit input[type=text], .edit textarea { width: 100%; padding: 9px 11px; border: 1px solid var(--line); border-radius: 8px; font-size: 14px; font-family: inherit; }
.edit input.bad { border-color: var(--danger); background: var(--danger-soft); }
.edit textarea { min-height: 60px; resize: vertical; }
.edit .err { color: var(--danger); font-size: 12px; margin-top: 4px; }
.taginput { border: 1px solid var(--line); border-radius: 8px; padding: 6px 8px; display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.taginput input { border: none; padding: 4px; flex: 1; min-width: 140px; outline: none; font-size: 14px; }
.taginput .chip { background: var(--accent-soft); color: var(--accent); font-size: 12px; padding: 3px 10px; border-radius: 999px; display: inline-flex; gap: 6px; align-items: center; border: none; }
.taginput .chip button { border: none; background: none; color: var(--accent); cursor: pointer; font-size: 13px; padding: 0; line-height: 1; }
.suggests { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.suggests .sug { border: 1px dashed var(--line); background: #fff; color: var(--muted); font-size: 12px; padding: 3px 10px; border-radius: 999px; cursor: pointer; }
.suggests .sug:hover { border-color: var(--accent); color: var(--accent); }
.editrow { display: flex; gap: 8px; margin-top: 12px; }
.confirm { background: var(--danger-soft); border: 1px solid var(--danger-line); border-radius: 10px; padding: 12px; margin-top: 10px; }
.confirm .q { color: var(--danger); font-weight: 600; font-size: 14px; margin: 0 0 4px; }
.confirm .sub { color: var(--muted); font-size: 12px; margin: 0 0 10px; }

